<script>
const payload=__BENCHMARK_DATA__;
const results=payload.results&&typeof payload.results==='object'?payload.results:payload;
const entries=Object.entries(results||{}).filter(([,r])=>r&&typeof r==='object').map(([name,r])=>({name,r}));
const numeric=value=>value===null||value===undefined||value===''?null:(Number.isFinite(Number(value))?Number(value):null);
const format=(value,digits=0)=>{const number=numeric(value);return number===null?'—':number.toLocaleString(undefined,{minimumFractionDigits:digits,maximumFractionDigits:digits})};
const compact=value=>{const number=numeric(value);if(number===null)return'—';return Intl.NumberFormat(undefined,{notation:'compact',maximumFractionDigits:1}).format(number)};
const metric=(r,name)=>numeric(r.remoteMetrics&&r.remoteMetrics[name]&&r.remoteMetrics[name].average);
const milliseconds=value=>{const number=numeric(value);return number===null?null:number*1000};const percent=value=>{const number=numeric(value);return number===null?null:number*100};
const statusClass=status=>status==='stable'?'badge-good':status==='unstable'?'badge-warn':'badge-bad';const statusLabel=status=>status?String(status).replaceAll('_',' '):'unknown';
const create=(tag,className,text)=>{const element=document.createElement(tag);if(className)element.className=className;if(text!==undefined)element.textContent=text;return element};
const humanDateTime=value=>{if(!value)return'Unknown recording time';const date=new Date(value);return Number.isNaN(date.getTime())?String(value):new Intl.DateTimeFormat(undefined,{year:'numeric',month:'long',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(date)};
document.getElementById('subtitle').textContent=`${humanDateTime(payload.recordedAt)} · ${entries.length} validated targets`;
const themeMedia=matchMedia('(prefers-color-scheme: dark)'),themeButton=document.getElementById('theme-toggle');let savedTheme=null;try{savedTheme=localStorage.getItem('benchmark-theme')}catch{}let themePreference=savedTheme==='light'||savedTheme==='dark'?savedTheme:'auto';
const themeCycle=()=>themeMedia.matches?['auto','light','dark']:['auto','dark','light'];const nextTheme=()=>{const choices=themeCycle(),index=choices.indexOf(themePreference);return choices[(index+1)%choices.length]};
function applyTheme(){const resolved=themePreference==='auto'?(themeMedia.matches?'dark':'light'):themePreference,label=themePreference[0].toUpperCase()+themePreference.slice(1),next=nextTheme();document.documentElement.dataset.bsTheme=resolved;themeButton.textContent=`Theme · ${label}`;themeButton.setAttribute('aria-label',themePreference==='auto'?`Theme follows your device setting. Activate to use ${next} theme.`:`Using ${label.toLowerCase()} theme. Activate to use ${next} theme.`);themeButton.title=themePreference==='auto'?'Automatically follows your device appearance':`Using ${label.toLowerCase()} appearance`}
applyTheme();themeButton.addEventListener('click',()=>{themePreference=nextTheme();try{if(themePreference==='auto')localStorage.removeItem('benchmark-theme');else localStorage.setItem('benchmark-theme',themePreference)}catch{}applyTheme()});themeMedia.addEventListener?.('change',()=>{if(themePreference==='auto')applyTheme()});
document.querySelectorAll('.tab-button').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.tab-button').forEach(item=>{item.classList.toggle('active',item===button);item.setAttribute('aria-selected',item===button?'true':'false')});document.querySelectorAll('.tab-pane').forEach(panel=>panel.classList.toggle('active',panel.id===`tab-${button.dataset.tab}`));history.replaceState(null,'',`#${button.dataset.tab}`)}));
const initialTab=location.hash.slice(1);if(initialTab&&document.querySelector(`[data-tab="${CSS.escape(initialTab)}"]`))document.querySelector(`[data-tab="${CSS.escape(initialTab)}"]`).click();
function addKpi(label,value,note,color){const card=create('article','kpi');card.style.setProperty('--kpi-accent',color);card.append(create('div','kpi-label',label),create('div','kpi-value',value),create('div','kpi-note',note));document.getElementById('kpis').appendChild(card)}
const stableEntries=entries.filter(({r})=>r.rankingStatus==='stable'&&numeric(r.stable&&r.stable.req_per_min)!==null);
